import sys

def main():
    data = sys.stdin.read().split()
    r, c = int(data[0]), int(data[1])
    g = [[int(data[2 + i * c + j]) for j in range(c)] for i in range(r)]
    ok = [[False] * (c + 1) for _ in range(r + 1)]
    for i in range(r - 1, -1, -1):
        for j in range(c - 1, -1, -1):
            if g[i][j] == 0:
                continue
            if i == r - 1 and j == c - 1:
                ok[i][j] = True
            else:
                ok[i][j] = ok[i + 1][j] or ok[i][j + 1]
    res = []
    if ok[0][0]:
        path = []
        def dfs(i, j):
            if i == r - 1 and j == c - 1:
                res.append(''.join(path))
                return
            if i + 1 < r and ok[i + 1][j]:
                path.append('D')
                dfs(i + 1, j)
                path.pop()
            if j + 1 < c and ok[i][j + 1]:
                path.append('R')
                dfs(i, j + 1)
                path.pop()
        dfs(0, 0)
    print(len(res))
    if res:
        sys.stdout.write('\n'.join(res) + '\n')

main()

